import {icon} from "./icons.js";
import {escapeHtml as esc} from "../account.js";
import {parseDate, WEEKDAYS} from "../date.js";
import {recurrenceLabel} from "../recurrence.js";
import {documentUrl} from "../documents.js";
import {eventTypeOptions} from "../event-types.js";

function recurrenceFields(draft) {
  const rule = draft.recurrence;
  const frequency = rule?.frequency || "none";
  const ending = rule?.until ? "until" : rule?.count ? "count" : "never";
  const weekdays = rule?.weekdays || [parseDate(draft.date).getUTCDay()];
  return `<div class="event-recurrence"><div class="event-field"><label class="field-label" for="event-frequency">Répétition</label><select id="event-frequency" name="recurrenceFrequency" aria-controls="event-recurrence-options">${[["none", "Ne se répète pas"], ["daily", "Chaque jour"], ["weekly", "Chaque semaine"], ["monthly", "Chaque mois"], ["yearly", "Chaque année"]].map(([value, label]) => `<option value="${value}" ${frequency === value ? "selected" : ""}>${label}</option>`).join("")}</select></div>
    <div id="event-recurrence-options" ${rule ? "" : "hidden"}>
      <div class="recurrence-interval"><label class="field-label" id="event-interval-prefix" for="event-interval">${frequency === "weekly" ? "Toutes les" : "Tous les"}</label><input id="event-interval" type="number" name="recurrenceInterval" min="1" max="99" step="1" value="${rule?.interval || 1}" ${rule ? "required" : "disabled"}/><span id="event-interval-unit">${({daily: "jours", weekly: "semaines", monthly: "mois", yearly: "ans"})[frequency] || "semaines"}</span></div>
      <fieldset id="event-weekdays" class="recurrence-weekdays" ${frequency === "weekly" ? "" : "hidden"}><legend class="field-label">Les jours suivants</legend><div>${[1, 2, 3, 4, 5, 6, 0].map(day => `<label title="${WEEKDAYS[day]}"><input type="checkbox" name="recurrenceWeekdays" value="${day}" aria-label="${WEEKDAYS[day]}" ${weekdays.includes(day) ? "checked" : ""} ${frequency === "weekly" ? "" : "disabled"}/><span>${WEEKDAYS[day].slice(0, 3)}</span></label>`).join("")}</div></fieldset>
      <div class="event-datetime recurrence-ending"><div class="event-field"><label class="field-label" for="event-recurrence-end">Fin de la répétition</label><select id="event-recurrence-end" name="recurrenceEnd" ${rule ? "" : "disabled"}>${[["never", "Jamais"], ["until", "À une date"], ["count", "Après un nombre d’occurrences"]].map(([value, label]) => `<option value="${value}" ${ending === value ? "selected" : ""}>${label}</option>`).join("")}</select></div>
      <div class="event-field" id="event-until-field" ${ending === "until" ? "" : "hidden"}><label class="field-label" for="event-until">Dernière date incluse</label><input id="event-until" type="date" name="recurrenceUntil" min="${esc(draft.date)}" max="9999-12-31" value="${rule?.until || draft.date}" ${rule && ending === "until" ? "required" : "disabled"}/></div>
      <div class="event-field" id="event-count-field" ${ending === "count" ? "" : "hidden"}><label class="field-label" for="event-count">Nombre d’occurrences</label><input id="event-count" type="number" name="recurrenceCount" min="1" max="1000" step="1" value="${rule?.count || 10}" ${rule && ending === "count" ? "required" : "disabled"}/></div></div>
      <p id="event-recurrence-summary" class="recurrence-summary" aria-live="polite">${esc(recurrenceLabel(rule))}</p><p id="event-recurrence-date-note" class="recurrence-summary" aria-live="polite" hidden></p>
      <div id="event-series-end-suggestion" class="recurrence-end-suggestion" hidden><p>La date de fin saisie termine chaque occurrence. Si elle doit terminer la série, utilise-la ici.</p><button type="button" class="secondary-button" data-action="event-use-end-date">Utiliser cette date pour terminer la série</button></div>
    </div></div>`;
}

export function eventDialog({event, date, aiAvailable, documents = [], documentsStatus = "loading", eventTypes = []}) {
  const editing = !!event;
  const draft = event || {title: "", description: "", date, endDate: date, startTime: "09:00", endTime: "10:00", allDay: false};
  const source = event?.source;
  const sourceRemoved = source && documentsStatus === "ready" && !documents.some(document => document.id === source.documentId);
  return `<dialog class="app-dialog event-dialog" aria-labelledby="event-dialog-title" aria-describedby="event-dialog-description">
    <header class="dialog-heading"><div><span class="event-dialog-eyebrow">${editing ? "TON CALENDRIER" : "UN MOMENT À PRÉVOIR"}</span><h2 id="event-dialog-title">${editing ? event.kind === "task" ? "Modifier la tâche" : "Modifier l’événement" : "Nouvel événement ou tâche"}</h2></div><button class="icon-button" data-action="close-event-dialog" aria-label="Fermer la fenêtre">${icon("close")}</button></header>
    <p class="dialog-description" id="event-dialog-description">${editing ? event.recurrence ? "Tu modifies toute la série. Les dates ci-dessous sont celles de la première occurrence." : "Ajuste les détails, puis enregistre tes changements." : "Un rendez-vous ou une tâche à accomplir. Décris-le, puis vérifie les détails."}</p>
    ${event?.moodle ? `<div class="event-document-source">${icon("external")}<div><span>MOODLE · ${esc(event.moodle.semester)}</span><a href="${esc(event.moodle.url)}" target="_blank" rel="noopener">Ouvrir sur Moodle ${icon("external")}</a>${event.kind === "task" && !event.moodle.personalDeadlineChecked ? "<small>Échéance du cours · prolongation personnelle non vérifiée</small>" : ""}</div></div>` : ""}
    ${source ? `<div class="event-document-source">${icon("document")}<div><span>DOCUMENT D’ORIGINE${source.page ? ` · PAGE ${source.page}` : ""}</span>${sourceRemoved ? `<strong>${esc(source.documentName)}</strong><small>Document supprimé de la bibliothèque</small>` : `<a href="${documentUrl(source.documentId, source.page, false, source.origin)}" target="_blank" rel="noopener">${esc(source.documentName)} ${icon("external")}</a>`}</div></div>` : ""}
    ${editing ? "" : `<div class="event-tabs" role="tablist" aria-label="Mode de création"><button id="natural-tab" role="tab" aria-controls="natural-panel" aria-selected="${aiAvailable}" tabindex="${aiAvailable ? 0 : -1}" data-action="event-natural">${icon("sparkles")}En quelques mots</button><button id="manual-tab" role="tab" aria-controls="manual-panel" aria-selected="${!aiAvailable}" tabindex="${aiAvailable ? -1 : 0}" data-action="event-manual">${icon("edit")}Saisir les détails</button></div>
    <section id="natural-panel" role="tabpanel" aria-labelledby="natural-tab" ${aiAvailable ? "" : "hidden"}><form id="event-interpret-form"><label class="field-label" for="event-prompt">Qu’est-ce que tu veux prévoir?</label><textarea id="event-prompt" name="text" rows="4" maxlength="2000" placeholder="Ex. : Souper avec Camille vendredi à 19 h, pendant deux heures, au restaurant du quartier." required></textarea><div class="prompt-examples"><span>Essaie aussi</span><button type="button" data-action="event-example" data-text="Dentiste demain à 14 h pendant 45 minutes">Dentiste demain à 14 h</button><button type="button" data-action="event-example" data-text="Congé vendredi, toute la journée">Congé vendredi</button></div><div class="dialog-actions"><button type="button" class="secondary-button" data-action="close-event-dialog">Annuler</button><button type="submit" class="primary-button">Préparer les détails ${icon("arrowRight")}</button></div></form></section>`}
    <section id="manual-panel" ${editing ? "" : 'role="tabpanel" aria-labelledby="manual-tab"'} ${!editing && aiAvailable ? "hidden" : ""}>
      ${!editing ? `<div id="event-review" class="event-review" role="status" hidden>${icon("check")}<span>Les détails sont prêts. Vérifie-les avant l’ajout.</span></div>${!aiAvailable ? '<p class="ai-offline-note">La création assistée est indisponible. Tu peux ajouter ton événement ici.</p>' : ""}` : ""}
      <form id="event-save-form"><div class="event-fields"><div class="event-field"><label class="field-label" for="event-kind">À ajouter</label><select id="event-kind" name="kind" ${event?.moodle ? "disabled" : ""}><option value="event" ${draft.kind !== "task" ? "selected" : ""}>Événement</option><option value="task" ${draft.kind === "task" ? "selected" : ""}>Tâche</option></select></div><div id="task-status-fields" ${draft.kind === "task" ? "" : "hidden"}><label class="all-day-toggle"><input type="checkbox" name="completed" ${draft.completed ? "checked" : ""}/><span id="task-completed-label">${draft.recurrence ? "Première occurrence terminée" : "Tâche terminée"}</span></label><label class="all-day-toggle"><input type="checkbox" name="hasDeadline" ${draft.deadline === null ? "" : "checked"}/><span>Avec une échéance</span></label></div><div class="event-field"><label class="field-label" for="event-title">Titre <span aria-hidden="true">*</span></label><input id="event-title" name="title" type="text" value="${esc(draft.title)}" placeholder="Donne un nom à ce moment" maxlength="160" required/></div>
      <div class="event-field"><label class="field-label" for="event-type">Type d’événement</label><select id="event-type" name="typeId">${eventTypeOptions(eventTypes, draft.typeId)}</select></div>
      <label id="event-all-day-toggle" class="all-day-toggle"><input type="checkbox" name="allDay" ${draft.allDay ? "checked" : ""}/><span>Toute la journée</span></label>
      <label id="event-multiday-toggle" class="all-day-toggle" hidden><input type="checkbox" name="occurrenceMultiDay" ${draft.endDate > draft.date ? "checked" : ""}/><span>Chaque occurrence dure plusieurs jours</span></label>
      <div id="event-start-datetime" class="event-datetime"><div class="event-field"><label id="event-date-label" class="field-label" for="event-date">Date de début</label><input id="event-date" type="date" name="date" value="${esc(draft.date)}" min="0001-01-01" max="9999-12-31" required/></div><div class="event-field event-time-field" ${draft.allDay ? "hidden" : ""}><label class="field-label" for="event-start">Heure de début</label><input id="event-start" type="time" name="startTime" value="${draft.startTime || "09:00"}" ${draft.allDay ? "disabled" : "required"}/></div></div>
      <div id="event-end-datetime" class="event-datetime"><div class="event-field"><label id="event-end-date-label" class="field-label" for="event-end-date">Date de fin</label><input id="event-end-date" type="date" name="endDate" value="${esc(draft.endDate)}" min="${esc(draft.date)}" max="9999-12-31" required/></div><div class="event-field event-time-field" ${draft.allDay ? "hidden" : ""}><label class="field-label" for="event-end">Heure de fin</label><input id="event-end" type="time" name="endTime" value="${draft.endTime || "10:00"}" ${draft.allDay ? "disabled" : "required"}/></div></div>
      <p id="event-occurrence-note" class="recurrence-summary" hidden>Ces dates décrivent une seule occurrence. La fin de la série se règle dans « Fin de la répétition ».</p>
      <p class="event-zone">${icon("globe")}Heure de Toronto <span>·</span> America/Toronto</p>${recurrenceFields(draft)}<p id="task-recurrence-note" class="recurrence-summary" ${draft.kind === "task" && draft.recurrence ? "" : "hidden"}>Chaque échéance se coche séparément dans le calendrier ou sur l’accueil. Les notes, liens et documents sont communs à toute la série.</p><div id="task-details-fields" ${draft.kind === "task" ? "" : "hidden"}>
        <div class="event-datetime"><div class="event-field"><label class="field-label" for="task-context-kind">Relier à</label><select id="task-context-kind" name="contextKind"><option value="">Aucun</option><option value="course" ${draft.context?.kind === "course" ? "selected" : ""}>Cours</option><option value="project" ${draft.context?.kind === "project" ? "selected" : ""}>Projet</option></select></div><div class="event-field"><label class="field-label" for="task-context-name">Nom du cours ou du projet</label><input id="task-context-name" name="contextName" type="text" maxlength="240" value="${esc(draft.context?.name || "")}"/></div></div>
        <div class="event-field"><label class="field-label" for="task-notes">Notes</label><textarea id="task-notes" name="notes" rows="3" maxlength="8000">${esc(draft.notes || "")}</textarea></div>
        <div class="event-field"><label class="field-label" for="task-links">Liens <span class="optional-label">un par ligne</span></label><textarea id="task-links" name="links" rows="2" placeholder="https://…">${esc((draft.links || []).join("\n"))}</textarea>${(draft.links || []).map((url, i) => `<a class="task-resource-link" href="${esc(url)}" target="_blank" rel="noopener">Lien ${i + 1} ${icon("external")}</a>`).join("")}</div>
        <fieldset class="task-document-list"><legend class="field-label">Documents de Bibliothèque</legend>${documents.length ? documents.map(file => `<label class="all-day-toggle"><input type="checkbox" name="documentIds" value="${esc(file.id)}" ${(draft.documentIds || []).includes(file.id) ? "checked" : ""}/><span>${esc(file.name)}</span>${(draft.documentIds || []).includes(file.id) ? `<a href="${documentUrl(file.id, null, false, "library")}" target="_blank" rel="noopener" aria-label="Ouvrir ${esc(file.name)}">${icon("external")}</a>` : ""}</label>`).join("") : `<p class="event-zone">${documentsStatus === "ready" ? "Ajoute tes documents dans Bibliothèque pour les relier ici." : "Chargement de Bibliothèque…"}</p>`}${(draft.documentIds || []).filter(id => !documents.some(file => file.id === id)).map(id => `<label class="all-day-toggle"><input type="checkbox" name="documentIds" value="${esc(id)}" checked/><span>Document indisponible</span></label>`).join("")}</fieldset>
      </div><div class="event-field"><label class="field-label" for="event-description">Description <span class="optional-label">facultative</span></label><textarea id="event-description" name="description" rows="3" maxlength="4000" placeholder="Un lieu, une note, quelque chose à ne pas oublier…">${esc(draft.description)}</textarea></div></div>
      <div class="dialog-actions event-save-actions">${editing ? `<button type="button" class="danger-link" data-action="event-delete">${icon("trash")}Supprimer</button>` : ""}<button type="button" class="secondary-button" data-action="close-event-dialog">Annuler</button><button type="submit" class="primary-button">${editing ? "Enregistrer" : "Ajouter au calendrier"} ${icon("check")}</button></div></form>
    </section><p id="event-error" class="event-error" role="alert" tabindex="-1" hidden></p>
    <section id="event-delete-confirm" class="event-confirm" aria-label="Confirmer la suppression" hidden><strong>${event?.recurrence ? "Supprimer toute la série?" : event?.kind === "task" ? "Supprimer cette tâche?" : "Supprimer cet événement?"}</strong><p>${event?.recurrence ? "Toutes les occurrences seront retirées de ton calendrier." : "Il sera retiré de ton calendrier."} ${event?.moodle ? "Cet élément ne sera pas réimporté automatiquement depuis Moodle." : "Cette action est définitive."}</p><div><button class="secondary-button" data-action="event-delete-cancel">${event?.recurrence ? "Garder la série" : "Garder l’événement"}</button><button class="danger-button" data-action="event-delete-confirm">${event?.recurrence ? "Supprimer la série" : "Supprimer l’événement"}</button></div></section>
    <section id="event-discard-confirm" class="event-confirm" aria-label="Modifications non enregistrées" hidden><strong>Quitter sans enregistrer?</strong><p>Les détails saisis dans cette fenêtre seront perdus.</p><div><button class="secondary-button" data-action="event-discard-cancel">Continuer</button><button class="danger-button" data-action="event-discard-confirm">Quitter</button></div></section>
  </dialog>`;
}
